$('new').onclick=()=>{if(fieldDrafts.size){message('Correct invalid fields or Discard before navigating.',true);return;}const input=el('input');input.id='new-name';input.value='Untitled component';input.setAttribute('aria-label','New component name');modal('New blank component',input,[button('Create blank',()=>closeAct(()=>d.create(input.value),'Created local blank draft.'))]);};
